def build_absence_report(people, sessions, end_day, window=7):
    if not hasattr(people, "items"):
        raise ValueError("people must be a mapping")
    if isinstance(end_day, bool) or not isinstance(end_day, int):
        raise ValueError("invalid end day")
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError("invalid window")

    person_items = list(people.items())
    for person, group in person_items:
        if not isinstance(person, str) or not person or not isinstance(group, str) or not group:
            raise ValueError("invalid person or group")
    known_people = {person for person, _ in person_items}
    known_groups = {group for _, group in person_items}
    parsed = []
    seen_days = set()

    for session in sessions:
        if not hasattr(session, "keys") or set(session.keys()) != {"day", "absent", "unreported_groups"}:
            raise ValueError("malformed session")
        day = session["day"]
        if isinstance(day, bool) or not isinstance(day, int) or day in seen_days:
            raise ValueError("invalid or duplicate day")
        seen_days.add(day)
        absent = tuple(session["absent"])
        unreported = tuple(session["unreported_groups"])
        if len(set(absent)) != len(absent) or any(person not in known_people for person in absent):
            raise ValueError("invalid absent list")
        if len(set(unreported)) != len(unreported) or any(group not in known_groups for group in unreported):
            raise ValueError("invalid unreported group list")
        parsed.append((day, absent, unreported))

    start = end_day - window + 1
    counts = {person: 0 for person, _ in person_items}
    ordered_groups = []
    seen_groups = set()
    for day, absent, unreported in sorted(parsed, key=lambda row: row[0]):
        if start < day <= end_day:
            for person in absent:
                counts[person] += 1
            for group in unreported:
                if group not in seen_groups:
                    seen_groups.add(group)
                    ordered_groups.append(group)
    return {"absence_counts": counts, "unreported_groups": tuple(ordered_groups)}

