import unittest
from collections import OrderedDict

from solution import build_absence_report


class AbsenceReportTests(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(build_absence_report({}, [], end_day=10), {
            'absence_counts': {}, 'unreported_groups': ()
        })

    def test_window_counts_order_ties_and_nonmutation(self):
        people = OrderedDict([('p2', 'blue'), ('p1', 'red'), ('p3', 'blue')])
        sessions = [
            {'day': 7, 'absent': ['p1'], 'unreported_groups': ['red']},
            {'day': 10, 'absent': ['p2', 'p1'], 'unreported_groups': ['blue', 'red']},
            {'day': 8, 'absent': ['p3'], 'unreported_groups': ['red']},
            {'day': 11, 'absent': ['p2'], 'unreported_groups': ['blue']},
        ]
        snapshot = [
            {'day': row['day'], 'absent': list(row['absent']),
             'unreported_groups': list(row['unreported_groups'])}
            for row in sessions
        ]
        result = build_absence_report(people, sessions, end_day=10, window=3)
        self.assertEqual(list(result['absence_counts']), ['p2', 'p1', 'p3'])
        self.assertEqual(result['absence_counts'], {'p2': 1, 'p1': 1, 'p3': 1})
        self.assertEqual(result['unreported_groups'], ('red', 'blue'))
        self.assertIsInstance(result['unreported_groups'], tuple)
        self.assertEqual(sessions, snapshot)

        sessions[1]['absent'].clear()
        self.assertEqual(result['absence_counts']['p2'], 1)

    def test_boundary_days_are_inclusive(self):
        people = {'a': 'g'}
        sessions = [
            {'day': 3, 'absent': ['a'], 'unreported_groups': []},
            {'day': 4, 'absent': ['a'], 'unreported_groups': []},
            {'day': 10, 'absent': ['a'], 'unreported_groups': []},
            {'day': 11, 'absent': ['a'], 'unreported_groups': []},
        ]
        result = build_absence_report(people, sessions, end_day=10, window=7)
        self.assertEqual(result['absence_counts'], {'a': 2})

    def test_accepts_one_pass_session_and_member_iterables(self):
        sessions = iter([{
            'day': 1,
            'absent': iter(['a']),
            'unreported_groups': iter(['g']),
        }])
        self.assertEqual(build_absence_report({'a': 'g'}, sessions, 1), {
            'absence_counts': {'a': 1}, 'unreported_groups': ('g',)
        })

    def test_rejects_invalid_people_window_and_end_day(self):
        for people in [[], {'': 'g'}, {1: 'g'}, {'a': ''}, {'a': 2}]:
            with self.subTest(people=people):
                with self.assertRaises(ValueError):
                    build_absence_report(people, [], 1)
        for window in [0, -1, True, 2.5]:
            with self.subTest(window=window):
                with self.assertRaises(ValueError):
                    build_absence_report({}, [], 1, window)
        for end_day in [True, 1.5, '1']:
            with self.subTest(end_day=end_day):
                with self.assertRaises(ValueError):
                    build_absence_report({}, [], end_day)

    def test_rejects_malformed_sessions_even_outside_window(self):
        valid = {'day': 1, 'absent': [], 'unreported_groups': []}
        cases = [
            [42],
            [{k: v for k, v in valid.items() if k != 'absent'}],
            [dict(valid, extra=[])],
            [dict(valid, day=True)],
            [{'day': 1, 'absent': ['missing'], 'unreported_groups': []}],
            [{'day': 1, 'absent': [], 'unreported_groups': ['missing']}],
            [{'day': 1, 'absent': ['a', 'a'], 'unreported_groups': []}],
            [{'day': 1, 'absent': [], 'unreported_groups': ['g', 'g']}],
            [valid, dict(valid)],
        ]
        for sessions in cases:
            with self.subTest(sessions=sessions):
                with self.assertRaises(ValueError):
                    build_absence_report({'a': 'g'}, sessions, end_day=100, window=1)


if __name__ == '__main__':
    unittest.main()

